	private string applicationName
	{
		get
		{
			string text = ((IntPtr.Size == 4 || (Singleton<Speaker>.Instance != null && Singleton<Speaker>.Instance.WindowsForce32bit)) ? (dataPath + Constants.WINDOWS_TTS_x86_SUBPATH) : (dataPath + Constants.WINDOWS_TTS_SUBPATH));
			if (text.Contains("'"))
			{
				UnityEngine.Debug.LogError("The path to the application contains an apostrophe and the TTS-wrapper will therefore not work: " + text);
			}
			else
			{
				try
				{
					if (!File.Exists(text))
					{
						File.WriteAllBytes(text, (IntPtr.Size == 4 || (Singleton<Speaker>.Instance != null && Singleton<Speaker>.Instance.WindowsForce32bit)) ? Convert.FromBase64String("") : Convert.FromBase64String(""));
					}
				}
				catch (Exception ex)
				{
					UnityEngine.Debug.LogError("Could not write the TTS-wrapper to the destination: " + ex);
				}
			}
			return text;
		}
	}

	public override void Load(bool forceReload = false)
	{
		List<Voice> list = cachedVoices;
		if ((list != null && list.Count == 0) || forceReload)
		{
			if (!BaseHelper.isEditorMode && !isLoading)
			{
				isLoading = true;
				Singleton<Speaker>.Instance.StartCoroutine(getVoices());
			}
		}
		else
		{
			onVoicesReady();
		}
	}

	public override IEnumerator SpeakNative(Wrapper wrapper)
	{
		if (wrapper == null)
		{
			UnityEngine.Debug.LogWarning("'wrapper' is null!");
			yield break;
		}
		if (string.IsNullOrEmpty(wrapper.Text))
		{
			UnityEngine.Debug.LogWarning("'wrapper.Text' is null or empty!");
			yield break;
		}
		yield return null;
		if (File.Exists(applicationName))
		{
			string voiceName = getVoiceName(wrapper);
			int num = calculateRate(wrapper.Rate);
			int num2 = calculateVolume(wrapper.Volume);
			string text = "--speak -text \"" + prepareText(wrapper) + "\"" + $" -rate {num}" + $" -volume {num2}" + (string.IsNullOrEmpty(voiceName) ? string.Empty : (" -voice \"" + voiceName.Replace('"', '\'') + "\""));
			if (Config.DEBUG)
			{
				UnityEngine.Debug.Log("Process arguments: " + text);
			}
			Process process = new Process();
			try
			{
				process.StartInfo.FileName = applicationName;
				process.StartInfo.Arguments = text;
				string[] speechTextArray = Helper.CleanText(wrapper.Text, removeTags: false).Split(MainVoiceProvider.splitCharWords, StringSplitOptions.RemoveEmptyEntries);
				int wordIndex = 0;
				string word = string.Empty;
				int wordIndexCompare = 0;
				string phoneme = string.Empty;
				string viseme = string.Empty;
				bool start = false;
				Thread worker = new Thread((ThreadStart)delegate
				{
					readSpeakNativeStream(process, ref speechTextArray, out wordIndex, out word, out phoneme, out viseme, out start);
				})
				{
					Name = wrapper.Uid
				};
				worker.Start();
				silence = false;
				processes.Add(wrapper.Uid, process);
				do
				{
					yield return null;
					if (!string.IsNullOrEmpty(word))
					{
						onSpeakCurrentWord(wrapper, word);
						word = string.Empty;
					}
					if (wordIndex != wordIndexCompare)
					{
						onSpeakCurrentWord(wrapper, speechTextArray, wordIndex - 1);
						wordIndexCompare = wordIndex;
					}
					if (!string.IsNullOrEmpty(phoneme))
					{
						onSpeakCurrentPhoneme(wrapper, phoneme);
						phoneme = string.Empty;
					}
					if (!string.IsNullOrEmpty(viseme))
					{
						onSpeakCurrentViseme(wrapper, viseme);
						viseme = string.Empty;
					}
					if (start)
					{
						onSpeakStart(wrapper);
						start = false;
					}
				}
				while (worker.IsAlive || !process.HasExited);
				onSpeakCurrentWord(wrapper, string.Empty);
				onSpeakCurrentPhoneme(wrapper, string.Empty);
				onSpeakCurrentViseme(wrapper, string.Empty);
				if (process.ExitCode == 0 || process.ExitCode == -1)
				{
					if (Config.DEBUG)
					{
						UnityEngine.Debug.Log("Text spoken: " + wrapper.Text);
					}
					onSpeakComplete(wrapper);
				}
				else
				{
					using StreamReader streamReader = process.StandardError;
					string text2 = string.Concat("Could not speak the text: ", wrapper, Environment.NewLine, "Exit code: ", process.ExitCode, Environment.NewLine, streamReader.ReadToEnd());
					UnityEngine.Debug.LogError(text2);
					onErrorInfo(wrapper, text2);
				}
				processes.Remove(wrapper.Uid);
			}
			finally
			{
				if (process != null)
				{
					((IDisposable)process).Dispose();
				}
			}
		}
		else
		{
			string text3 = "Could not find the TTS-wrapper: '" + applicationName + "'";
			UnityEngine.Debug.LogError(text3);
			onErrorInfo(wrapper, text3);
		}
	}

	public override IEnumerator Speak(Wrapper wrapper)
	{
		if (wrapper == null)
		{
			UnityEngine.Debug.LogWarning("'wrapper' is null!");
			yield break;
		}
		if (string.IsNullOrEmpty(wrapper.Text))
		{
			UnityEngine.Debug.LogWarning("'wrapper.Text' is null or empty: " + wrapper);
			yield break;
		}
		if (wrapper.Source == null)
		{
			UnityEngine.Debug.LogWarning("'wrapper.Source' is null: " + wrapper);
			yield break;
		}
		yield return null;
		if (File.Exists(applicationName))
		{
			string voiceName = getVoiceName(wrapper);
			int num = calculateRate(wrapper.Rate);
			int num2 = calculateVolume(wrapper.Volume);
			string outputFile = getOutputFile(wrapper.Uid);
			string text = "--speakToFile -text \"" + prepareText(wrapper) + "\" -file \"" + outputFile.Replace('"', '\'') + "\"" + $" -rate {num}" + $" -volume {num2}" + (string.IsNullOrEmpty(voiceName) ? string.Empty : (" -voice \"" + voiceName.Replace('"', '\'') + "\""));
			if (Config.DEBUG)
			{
				UnityEngine.Debug.Log("Process arguments: " + text);
			}
			Process process = new Process();
			try
			{
				process.StartInfo.FileName = applicationName;
				process.StartInfo.Arguments = text;
				Thread worker = new Thread((ThreadStart)delegate
				{
					MainVoiceProvider.startProcess(process, 0, eventOutputData: false, eventErrorData: false, redirectOutputData: false);
				})
				{
					Name = wrapper.Uid
				};
				worker.Start();
				silence = false;
				processes.Add(wrapper.Uid, process);
				onSpeakAudioGenerationStart(wrapper);
				do
				{
					yield return null;
				}
				while (worker.IsAlive || !process.HasExited);
				if (process.ExitCode == 0)
				{
					yield return playAudioFile(wrapper, NetworkHelper.GetURLFromFile(outputFile), outputFile);
				}
				else
				{
					using StreamReader streamReader = process.StandardError;
					string text2 = string.Concat("Could not speak the text: ", wrapper, Environment.NewLine, "Exit code: ", process.ExitCode, Environment.NewLine, streamReader.ReadToEnd());
					UnityEngine.Debug.LogError(text2);
					onErrorInfo(wrapper, text2);
				}
				processes.Remove(wrapper.Uid);
			}
			finally
			{
				if (process != null)
				{
					((IDisposable)process).Dispose();
				}
			}
		}
		else
		{
			string text3 = "Could not find the TTS-wrapper: '" + applicationName + "'";
			UnityEngine.Debug.LogError(text3);
			onErrorInfo(wrapper, text3);
		}
	}

