	private IEnumerator getVoices()
	{
		if (File.Exists(applicationName))
		{
			List<Voice> voices = new List<Voice>();
			Process process = new Process();
			try
			{
				process.StartInfo.FileName = applicationName;
				process.StartInfo.Arguments = "--voices";
				Thread worker = new Thread((ThreadStart)delegate
				{
					MainVoiceProvider.startProcess(process, 7000);
				});
				worker.Start();
				do
				{
					yield return null;
				}
				while (worker.IsAlive || !process.HasExited);
				if (process.ExitCode == 0)
				{
					using StreamReader streamReader = process.StandardOutput;
					while (!streamReader.EndOfStream)
					{
						string text = streamReader.ReadLine();
						if (Config.DEBUG)
						{
							UnityEngine.Debug.Log("reply: " + text);
						}
						if (!string.IsNullOrEmpty(text) && text.CTStartsWith("@VOICE:"))
						{
							string[] array = text.Split(splitChar, StringSplitOptions.RemoveEmptyEntries);
							if (array.Length == 6)
							{
								voices.Add(new Voice(array[1], array[2], Helper.StringToGender(array[3]), array[4], array[5]));
							}
							else
							{
								UnityEngine.Debug.LogWarning("Voice is invalid: " + text);
							}
						}
					}
				}
				else
				{
					using StreamReader streamReader2 = process.StandardError;
					string text2 = "Could not get any voices: " + process.ExitCode + Environment.NewLine + streamReader2.ReadToEnd();
					UnityEngine.Debug.LogError(text2);
					onErrorInfo(null, text2);
				}
			}
			finally
			{
				if (process != null)
				{
					((IDisposable)process).Dispose();
				}
			}
			cachedVoices = voices.OrderBy((Voice s) => s.Name).ToList();
			if (BaseConstants.DEV_DEBUG)
			{
				UnityEngine.Debug.Log("Voices read: " + cachedVoices.CTDump());
			}
		}
		else
		{
			string text3 = "Could not find the TTS-wrapper: '" + applicationName + "'";
			UnityEngine.Debug.LogError(text3);
			onErrorInfo(null, text3);
		}
		isLoading = false;
		onVoicesReady();
	}

	private static void readSpeakNativeStream(Process process, ref string[] speechTextArray, out int wordIndex, out string word, out string phoneme, out string viseme, out bool start, bool redirectOutputData = true, bool redirectErrorData = true)
	{
		wordIndex = 0;
		word = string.Empty;
		phoneme = string.Empty;
		viseme = string.Empty;
		start = false;
		process.StartInfo.CreateNoWindow = true;
		process.StartInfo.RedirectStandardOutput = redirectOutputData;
		process.StartInfo.RedirectStandardError = redirectErrorData;
		process.StartInfo.UseShellExecute = false;
		ProcessStartInfo startInfo = process.StartInfo;
		Encoding standardErrorEncoding = (process.StartInfo.StandardOutputEncoding = Encoding.UTF8);
		startInfo.StandardErrorEncoding = standardErrorEncoding;
		try
		{
			process.Start();
			using StreamReader streamReader = process.StandardOutput;
			string text = streamReader.ReadLine();
			if (!string.IsNullOrEmpty(text) && "@SPEAK".Equals(text))
			{
				while (!process.HasExited)
				{
					text = streamReader.ReadLine();
					if (string.IsNullOrEmpty(text))
					{
						continue;
					}
					if (text.CTStartsWith("@WORD"))
					{
						word = text.Substring("@WORD".Length + 1);
						if (BaseConstants.DEV_DEBUG)
						{
							UnityEngine.Debug.Log("Word spoken: " + word);
						}
						if (wordIndex < speechTextArray.Length)
						{
							if (speechTextArray[wordIndex].Equals("-"))
							{
								wordIndex++;
							}
							wordIndex++;
						}
					}
					else if (text.CTStartsWith("@PHONEME:"))
					{
						string[] array = text.Split(splitChar, StringSplitOptions.RemoveEmptyEntries);
						if (array.Length > 1)
						{
							phoneme = array[1];
							if (BaseConstants.DEV_DEBUG)
							{
								UnityEngine.Debug.Log("Phoneme spoken: " + phoneme);
							}
						}
					}
					else if (text.CTStartsWith("@VISEME:"))
					{
						string[] array2 = text.Split(splitChar, StringSplitOptions.RemoveEmptyEntries);
						if (array2.Length > 1)
						{
							viseme = array2[1];
							if (BaseConstants.DEV_DEBUG)
							{
								UnityEngine.Debug.Log("Viseme spoken: " + viseme);
							}
						}
					}
					else if (text.Equals("@STARTED"))
					{
						start = true;
					}
				}
			}
			else if (process.StartInfo.RedirectStandardOutput)
			{
				UnityEngine.Debug.LogError("Unexpected process output: " + text + Environment.NewLine + streamReader.ReadToEnd());
			}
		}
		catch (Exception ex)
		{
			UnityEngine.Debug.LogError("Could not speak: " + ex);
		}
	}

	private static string prepareText(Wrapper wrapper)
	{
		if (wrapper.ForceSSML && !Singleton<Speaker>.Instance.AutoClearTags)
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append("<?xml version=\"1.0\" encoding=\"UTF-8\" ?>");
			stringBuilder.Append("<speak version=\"1.0\" xmlns=\"http://www.w3.org/2001/10/synthesis\" xml:lang=\"");
			stringBuilder.Append((wrapper.Voice == null) ? "en-US" : wrapper.Voice.Culture);
			stringBuilder.Append("\">");
			float num = wrapper.Pitch - 1f;
			if (Mathf.Abs(num) > 0.0001f)
			{
				stringBuilder.Append("<prosody pitch='");
				stringBuilder.Append((num > 0f) ? num.ToString("+#0%", BaseHelper.BaseCulture) : num.ToString("#0%", BaseHelper.BaseCulture));
				stringBuilder.Append("'>");
			}
			stringBuilder.Append(wrapper.Text);
			if (Mathf.Abs(num) > 0.0001f)
			{
				stringBuilder.Append("</prosody>");
			}
			stringBuilder.Append("</speak>");
			return MainVoiceProvider.getValidXML(stringBuilder.ToString().Replace('"', '\''));
		}
		return wrapper.Text.Replace('"', '\'');
	}

	private static int calculateVolume(float volume)
	{
		return Mathf.Clamp((int)(100f * volume), 0, 100);
	}

	private static int calculateRate(float rate)
	{
		int num = 0;
		if (Mathf.Abs(rate - 1f) > 0.0001f)
		{
			if (rate > 1f)
			{
				if (rate >= 2.75f)
				{
					num = 10;
				}
				else if (rate >= 2.6f && rate < 2.75f)
				{
					num = 9;
				}
				else if (rate >= 2.35f && rate < 2.6f)
				{
					num = 8;
				}
				else if (rate >= 2.2f && rate < 2.35f)
				{
					num = 7;
				}
				else if (rate >= 2f && rate < 2.2f)
				{
					num = 6;
				}
				else if (rate >= 1.8f && rate < 2f)
				{
					num = 5;
				}
				else if (rate >= 1.6f && rate < 1.8f)
				{
					num = 4;
				}
				else if (rate >= 1.4f && rate < 1.6f)
				{
					num = 3;
				}
				else if (rate >= 1.2f && rate < 1.4f)
				{
					num = 2;
				}
				else if (rate > 1f && rate < 1.2f)
				{
					num = 1;
				}
			}
			else if (rate <= 0.3f)
			{
				num = -10;
			}
			else if ((double)rate > 0.3 && rate <= 0.4f)
			{
				num = -9;
			}
			else if ((double)rate > 0.4 && rate <= 0.45f)
			{
				num = -8;
			}
			else if ((double)rate > 0.45 && rate <= 0.5f)
			{
				num = -7;
			}
			else if ((double)rate > 0.5 && rate <= 0.55f)
			{
				num = -6;
			}
			else if ((double)rate > 0.55 && rate <= 0.6f)
			{
				num = -5;
			}
			else if ((double)rate > 0.6 && rate <= 0.7f)
			{
				num = -4;
			}
			else if ((double)rate > 0.7 && rate <= 0.8f)
			{
				num = -3;
			}
			else if ((double)rate > 0.8 && rate <= 0.9f)
			{
				num = -2;
			}
			else if ((double)rate > 0.9 && rate < 1f)
			{
				num = -1;
			}
		}
		if (BaseConstants.DEV_DEBUG)
		{
			UnityEngine.Debug.Log("calculateRate: " + num + " - " + rate);
		}
		return num;
	}
}
